<!--vbase-->
<template>
  <button
    v-if="fullWidth"
    type="button"
    class="social-btn-full"
    data-test="login-google-button"
    @click="oauthSignIn()"
  >
    <img src="/images/google.svg" width="20" height="20" alt="Google" />
    <span class="social-btn-text">{{ $t('sign_in_with_google') }}</span>
  </button>
  <q-btn
    v-else
    class="social-btn-icon"
    data-test="login-google-button"
    flat
    rounded
    @click="oauthSignIn()"
  >
    <img
      src="/images/google.svg"
      :style="{ height: height + 'px', width: width + 'px' }"
      alt="Google"
    />
  </q-btn>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { api } from 'pages/APIs';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import selectApps from 'src/utils/selectApps';
import { LOGIN_PARAMS } from 'src/constants';
import { ApiExceptions } from 'src/exceptions/index';
import {
  getObjectFromIndexDbWithExpiry,
  saveObjectToIndexDbWithExpiry,
  deleteObjectFromIndexDb,
} from 'src/utils/indexedDb';

export default defineComponent({
  el: '#app',
  mixins: [selectApps],
  props: {
    height: {
      type: Number,
      default: 24,
    },
    width: {
      type: Number,
      default: 24,
    },
    fullWidth: {
      type: Boolean,
      default: false,
    },
  },
  components: {},
  data() {
    return {
      current_page_url: '',
      social_status: ref(''),
    };
  },
  mounted: function () {
    this.setPageRoute();
    this.current_page_url = (<any>window).location.origin;
    setTimeout(() => {
      this.handleSocialMediaRedirect();
    }, 0);
  },
  watch: {},
  methods: {
    async handleSocialMediaRedirect() {
      try {
        let code = this.getAccessTokenCode();
        if (!code) {
          return;
        }
        // Extract redirect URL from state parameter if it exists
        const redirectUrl = await getObjectFromIndexDbWithExpiry(LOGIN_PARAMS);
        await deleteObjectFromIndexDb(LOGIN_PARAMS);

        const event = new CustomEvent('social_media_login_after', {
          detail: {
            access_type: 'google',
            access_token: code,
            redirect: redirectUrl, // Pass the redirect URL to the event handler
          },
        });
        document.dispatchEvent(event);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
      }
    },
    getAccessTokenCode() {
      let status = this.$route.query.state || '';
      if (
        !this.$route.query ||
        status.includes('google') !== true ||
        !this.$route.query.code
      ) {
        return;
      }
      let code = this.$route.query.code;
      return typeof code === 'string' ? code : '';
    },
    parseRouteParams() {
      let raw_params = this.$route.hash;
      let params = {} as dynamicObj;
      let splited_str = ((raw_params as string) || '').split('&');

      for (const [key, value] of Object.entries(splited_str)) {
        let split_param = ((value as string) || '').split('=');
        if (Array.isArray(split_param) && split_param.length == 2) {
          let key = split_param[0].replace('#', '');
          params[key] = split_param[1];
        }
      }
      return params;
    },
    oauthSignIn() {
      if (!process.env.APP_VUE_GOOGLE_CLIENT_ID) {
        logInfo('Google credential missing');
        return;
      }
      this.setExtraParamsToSession();

      var oauth2Endpoint = api.google_oauth2_endpoint;
      var form = document.createElement('form');
      form.setAttribute('method', 'GET');
      form.setAttribute('action', oauth2Endpoint);

      var params = {
        client_id: process.env.APP_VUE_GOOGLE_CLIENT_ID,
        redirect_uri: this.current_page_url,
        response_type: 'code',
        scope:
          'email profile openid https://www.googleapis.com/auth/userinfo.email https://www.googleapis.com/auth/userinfo.profile',
        include_granted_scopes: 'true',
        state: this.social_status,
      };

      for (const [key, val] of Object.entries(params)) {
        let value = val;
        var input = document.createElement('input');
        input.setAttribute('type', 'hidden');
        input.setAttribute('name', key);
        input.setAttribute('value', value);
        form.appendChild(input);
      }

      document.body.appendChild(form);
      form.submit();
    },
    setPageRoute() {
      this.social_status = this.getStatusByRoute(this.$route.path);
      this.social_status += 'google';
    },
    async setExtraParamsToSession() {
      const redirectParam = this.$route.query.redirect;
      if (!redirectParam) {
        return;
      }

      await saveObjectToIndexDbWithExpiry(LOGIN_PARAMS, redirectParam);
    },
  },
  setup() {
    return {};
  },
});
</script>

